import {Inputs, html} from "@observablehq/inputs"

trainData














viewof filterText = Inputs.text({label: "PID:", placeholder: "e.g. 577618"})

// Filtered data
filteredPoints = trainData.filter(d =&gt; 
  d.PID.includes(filterText)
)

// --- MAP CONTAINER ---
html`&lt;div id="map" style="height: 600px;"&gt;&lt;/div&gt;`





















{
  // Check if map already exists and remove it
  if (window.myLeafletMap) {
    window.myLeafletMap.remove();
    window.myLeafletMap = null;
  }

  // Create new Leaflet map and store reference globally
  const map = L.map("map").setView([40.78, -73.96], 13);
  window.myLeafletMap = map;

  // Add CartoDB basemap
  L.tileLayer("https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png", {
    attribution: '&copy; &lt;a href="https://carto.com/"&gt;CARTO&lt;/a&gt; | Map data © OpenStreetMap contributors',
    subdomains: "abcd",
    maxZoom: 19
  }).addTo(map);

  // Add filtered markers
  filteredPoints.forEach(d =&gt; {
    const popup = `
      &lt;strong&gt;PID:&lt;/strong&gt; ${d.PID}&lt;br&gt;
      &lt;strong&gt;SALEKEY:&lt;/strong&gt; ${d.SALEKEY}&lt;br&gt;
      &lt;strong&gt;Sale Price:&lt;/strong&gt; $${(+d.GROSSCON).toLocaleString()}&lt;br&gt;
      &lt;strong&gt;Predicted:&lt;/strong&gt; $${(+d.prediction).toLocaleString()}&lt;br&gt;
      &lt;strong&gt;Sales Ratio:&lt;/strong&gt; ${(+d.sales_ratio).toFixed(3)}&lt;br&gt;&lt;br&gt;
      &lt;strong&gt;BEDROOMS:&lt;/strong&gt; ${d.BEDROOMS}, &lt;strong&gt;BATHROOMS:&lt;/strong&gt; ${d.BATHROOMS}&lt;br&gt;
      &lt;strong&gt;Subway Dist:&lt;/strong&gt; ${d.subway_dist}, &lt;strong&gt;Park Dist:&lt;/strong&gt; ${d.park_dist}
    `;

    L.circleMarker([+d.lat, +d.lon], {
      radius: 6,
      color: "black",
      fillColor: "#2A93D5",
      fillOpacity: 0.7,
      weight: 1
    }).addTo(map).bindPopup(popup);
  });
}

